import { readFileSync,writeFileSync } from 'node:fs';
import { spawnSync } from 'node:child_process';

// Wrangler --check compares its config hash, not declaration-body edits. Compare
// the actual regenerated bytes and always restore the checked-in file afterwards.
const path='worker-configuration.d.ts',original=readFileSync(path);
try {
  const result=spawnSync(process.execPath,['node_modules/wrangler/bin/wrangler.js','types','--env','staging','--include-runtime','false','--strict-vars','false'],{stdio:'inherit',env:process.env});
  if(result.error)throw result.error;
  if(result.status!==0)throw Error('Worker binding type generation failed');
  if(!original.equals(readFileSync(path)))throw Error('Worker binding types drift; run npm run types and review the change');
} finally {writeFileSync(path,original);}
